import os

def safe_upload_path(upload_dir: str, filename: str) -> str:
    if not os.path.isdir(upload_dir):
        raise ValueError("upload_dir is not a valid directory")

    safe_path = os.path.abspath(os.path.join(upload_dir, filename))

    if not safe_path.startswith(os.path.abspath(upload_dir)):
        raise ValueError("File path traversal detected")

    return safe_path
